import os

import boto3
from botocore.exceptions import BotoCoreError, ClientError


def fetch_api_key(secret_name: str, region_name: str | None = None) -> str:
    region = region_name or os.getenv("AWS_REGION") or os.getenv("AWS_DEFAULT_REGION") or "us-east-1"
    client = boto3.client("secretsmanager", region_name=region)

    try:
        response = client.get_secret_value(SecretId=secret_name)
    except (BotoCoreError, ClientError) as e:
        raise RuntimeError(f"Failed to fetch secret from AWS Secrets Manager: {e}") from e

    if "SecretString" in response and response["SecretString"]:
        return response["SecretString"]

    if "SecretBinary" in response and response["SecretBinary"]:
        binary_secret = response["SecretBinary"]
        if isinstance(binary_secret, bytes):
            return binary_secret.decode("utf-8")
        return binary_secret

    raise RuntimeError(f"Secret '{secret_name}' was returned without a usable value.")
